with tempfile.TemporaryDirectory(prefix='leotv-vlc-lifecycle-') as temporary:
    work=Path(temporary);paths=[]
    for name,content in FIXTURES.items():
        path=work/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content);paths.append(path)
    production=[ROOT/'player/vlc/java/com/leotv/player/vlc'/name for name in ('VlcBridge.java','VlcEngine.java','VlcClock.java','VlcHttpProxy.java')]
    subprocess.run(['javac','--release','8','-encoding','UTF-8','-d',str(work/'classes'),*map(str,production+paths)],check=True)
    subprocess.run(['java','-cp',str(work/'classes'),'com.leotv.player.vlc.LifecycleContract'],check=True,timeout=20)
